struct TreeNode *inorderSuccessor(struct TreeNode *root, struct TreeNode *p) {
  if (p->right) {
    struct TreeNode *node = p->right;
    while (node->left) node = node->left;
    return node;
  }
  struct TreeNode *succ = NULL, *node = root;
  while (node) {
    if (p->val < node->val) {
      succ = node;
      node = node->left;
    } else if (p->val > node->val) {
      node = node->right;
    } else {
      break;
    }
  }
  return succ;
}

