class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  public TreeNode inorderSuccessor(TreeNode root, TreeNode p) {
    if (p.right != null) {
      TreeNode node = p.right;
      while (node.left != null) node = node.left;
      return node;
    }
    TreeNode succ = null, node = root;
    while (node != null) {
      if (p.val < node.val) {
        succ = node;
        node = node.left;
      } else if (p.val > node.val) {
        node = node.right;
      } else {
        break;
      }
    }
    return succ;
  }
}

class Solution:
    def inorderSuccessor(self, root: TreeNode, p: TreeNode) -> Optional[TreeNode]:
        if p.right:
            node = p.right
            while node.left:
                node = node.left
            return node
        succ = None
        node = root
        while node:
            if p.val < node.val:
                succ = node
                node = node.left
            elif p.val > node.val:
                node = node.right
            else:
                break
        return succ

impl Solution {
  pub fn inorder_successor(root: &Option<Box<TreeNode>>, p: i32) -> Option<i32> {
    fn find(node: &Option<Box<TreeNode>>, val: i32) -> Option<&Box<TreeNode>> {
      match node {
        None => None,
        Some(n) => {
          if n.val == val {
            Some(n)
          } else if val < n.val {
            find(&n.left, val)
          } else {
            find(&n.right, val)
          }
        }
      }
    }
    let pnode = find(root, p).unwrap();
    if let Some(right) = &pnode.right {
      let mut node = right;
      while let Some(l) = &node.left {
        node = l;
      }
      return Some(node.val);
    }
    let mut succ = None;
    let mut node = root;
    while let Some(n) = node {
      if p < n.val {
        succ = Some(n.val);
        node = &n.left;
      } else if p > n.val {
        node = &n.right;
      } else {
        break;
      }
    }
    succ
  }
}

const inorderSuccessor = (root: TreeNode | null, p: TreeNode): TreeNode | null => {
  if (p.right) {
    let node = p.right;
    while (node.left) node = node.left;
    return node;
  }
  let succ: TreeNode | null = null;
  let node = root;
  while (node) {
    if (p.val < node.val) {
      succ = node;
      node = node.left;
    } else if (p.val > node.val) {
      node = node.right;
    } else {
      break;
    }
  }
  return succ;
};
